def gen(rng):
    def build(n, vlo, vhi, maxdepth=None, spine=0, shape='random'):
        # parent[i] < i; depth[i] counted in nodes (root depth 1)
        par = [-1] * n
        depth = [1] * n
        for i in range(1, n):
            if i < spine:
                par[i] = i - 1
            elif shape == 'star':
                par[i] = 0
            else:
                while True:
                    j = rng.randrange(i) if shape == 'random' else rng.randrange(max(0, i - 5), i)
                    if maxdepth is None or depth[j] < maxdepth:
                        break
                par[i] = j
            depth[i] = depth[par[i]] + 1
        perm = list(range(1, n))
        rng.shuffle(perm)
        perm = [0] + perm
        vals = [rng.randint(vlo, vhi) for _ in range(n)]
        out_vals = [0] * n
        for i in range(n):
            out_vals[perm[i]] = vals[i]
        edges = []
        for i in range(1, n):
            a, b = perm[par[i]], perm[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b))
        rng.shuffle(edges)
        return str(n) + '\n' + ' '.join(map(str, out_vals)) + '\n' + '\n'.join('%d %d' % e for e in edges)
    tests = [
        '1\n5',
        '1\n-7',
        '2\n3 4\n1 0',
        '2\n3 -4\n0 1',
        '3\n1 2 3\n0 1\n0 2',
        '4\n5 -3 2 10\n0 1\n1 2\n2 3',
    ]
    for n in (3, 5, 8, 12, 16, 25):
        for _ in range(3):
            tests.append(build(n, -9, 9, shape=rng.choice(['random', 'path'])))
    for n in (6, 10, 20):
        tests.append(build(n, 1, 9))
        tests.append(build(n, -20, -1))
    tests.append(build(100000, -10**9, 10**9, maxdepth=5000, spine=5000))
    tests.append(build(100000, 1, 10**9, maxdepth=5000, spine=5000))
    tests.append(build(100000, -10**9, 10**9, shape='star'))
    tests.append(build(100000, -1000, 1000, maxdepth=60))
    tests.append(build(5000, -10**9, 10**9, spine=5000))
    return tests
